import React, { useState, useRef, useEffect } from "react";
import { Check, ChevronDown, Sparkles, ArrowRight } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useNavigate } from "react-router-dom";

/* ---------------- Company Data ---------------- */

const BIG_TECH_COMPANIES = [
  { name: "Google", logo: "data:image/jpeg;base64,", color: "#4285F4", bg: "#EBF3FE", gradient: "from-blue-50 via-indigo-50 to-blue-100" },
  { name: "Microsoft", logo: "data:image/png;base64,", color: "#00A4EF", bg: "#E5F5FE", gradient: "from-sky-50 via-blue-50 to-cyan-100" },
  { name: "Amazon", logo: "data:image/jpeg;base64,", color: "#FF9900", bg: "#FFF4E0", gradient: "from-amber-50 via-orange-50 to-yellow-100" },
  { name: "Meta", logo: "data:image/png;base64,", color: "#0866FF", bg: "#EBF3FE", gradient: "from-blue-50 via-indigo-50 to-violet-100" },
  { name: "Apple", logo: "data:image/png;base64,", color: "#555555", bg: "#F2F2F2", gradient: "from-gray-50 via-slate-50 to-gray-100" },
  { name: "Netflix", logo: "data:image/png;base64,", color: "#E50914", bg: "#FDECEA", gradient: "from-red-50 via-rose-50 to-red-100" },
  { name: "Nvidia", logo: "data:image/png;base64,", color: "#76B900", bg: "#F0F8E5", gradient: "from-green-50 via-lime-50 to-green-100" },
  { name: "Salesforce", logo: "data:image/png;base64,", color: "#00A1E0", bg: "#E5F6FD", gradient: "from-cyan-50 via-sky-50 to-blue-100" },
  { name: "Adobe", logo: "data:image/png;base64,", color: "#FF0000", bg: "#FDECEA", gradient: "from-red-50 via-pink-50 to-rose-100" },
  { name: "Uber", logo: "data:image/png;base64,", color: "#1a1a1a", bg: "#F0F0F0", gradient: "from-slate-50 via-gray-50 to-zinc-100" },
  { name: "Airbnb", logo: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQJPgPCQ5o_XNfriYRAbp1UKCW8opXlkJZNqQ&s", color: "#FF5A5F", bg: "#FFF0F0", gradient: "from-rose-50 via-pink-50 to-red-100" },
  { name: "Spotify", logo: "data:image/png;base64,", color: "#1DB954", bg: "#E8F8ED", gradient: "from-emerald-50 via-green-50 to-teal-100" },
];

/* ---------------- Selection Button ---------------- */

const SelectionButton = ({ value, options, onSelect, disabled = false, placeholder, className = "", dropdownDirection = "down" }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [roleWarning, setRoleWarning] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (ref.current && !ref.current.contains(event.target)) setIsOpen(false);
    };
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  return (
    <div className={`relative w-full ${className}`} ref={ref}>
      <motion.button
        whileHover={!disabled ? { scale: 1.01 } : {}}
        whileTap={!disabled ? { scale: 0.99 } : {}}
        onClick={() => {
          if (!disabled) setIsOpen(!isOpen);
          else { setRoleWarning(true); setTimeout(() => setRoleWarning(false), 3000); }
        }}
        disabled={disabled}
        className={`w-full px-6 py-4 rounded-2xl text-left border-2 transition-all font-medium flex items-center justify-between
          ${disabled
            ? "bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed"
            : "bg-white/90 backdrop-blur-sm text-gray-900 border-gray-200 hover:border-[#D4F478] hover:bg-white shadow-sm hover:shadow-md"
          }`}
      >
        <span className={!value ? "text-gray-400" : "text-gray-900"}>{value || placeholder}</span>
        <motion.div animate={{ rotate: isOpen ? 180 : 0 }} transition={{ duration: 0.3 }}>
          <ChevronDown className={`w-5 h-5 ${disabled ? "text-gray-400" : "text-gray-600"}`} />
        </motion.div>
      </motion.button>

      <AnimatePresence>
        {isOpen && options.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: dropdownDirection === "down" ? -10 : 10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: dropdownDirection === "down" ? -10 : 10, scale: 0.95 }}
            transition={{ duration: 0.2 }}
            className={`absolute z-50 w-full bg-white/95 backdrop-blur-xl rounded-2xl shadow-2xl border-2 border-gray-100 max-h-64 overflow-y-auto
              ${dropdownDirection === "down" ? "top-full mt-2" : "bottom-full mb-2"}`}
          >
            {options.map((option, index) => (
              <motion.div
                key={option}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.03 }}
                onClick={(e) => { e.stopPropagation(); onSelect(option); setIsOpen(false); }}
                className={`px-6 py-3.5 cursor-pointer flex justify-between items-center transition-colors
                  ${value === option ? "bg-[#D4F478]/20 font-bold text-gray-900" : "hover:bg-gray-50 text-gray-700"}
                  ${index === 0 ? "rounded-t-2xl" : ""}
                  ${index === options.length - 1 ? "rounded-b-2xl" : ""}`}
              >
                {option}
                {value === option && (
                  <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", stiffness: 300 }}>
                    <Check className="w-5 h-5 text-[#1A1A1A]" strokeWidth={3} />
                  </motion.div>
                )}
              </motion.div>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {roleWarning && disabled && (
          <motion.p initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -5 }}
            className="text-sm text-red-500 font-medium text-center mt-2">
            Please select a Company first.
          </motion.p>
        )}
      </AnimatePresence>
    </div>
  );
};

/* ---------------- Company Card ---------------- */

const CompanyCard = ({ company, isSelected, onClick }) => {
  const [hovered, setHovered] = useState(false);

  return (
    <motion.button
      onClick={onClick}
      onHoverStart={() => setHovered(true)}
      onHoverEnd={() => setHovered(false)}
      whileHover={{ y: -5, scale: 1.03 }}
      whileTap={{ scale: 0.96 }}
      transition={{ type: "spring", stiffness: 300, damping: 20 }}
      className="relative flex flex-col items-center justify-center gap-3 p-5 rounded-3xl cursor-pointer focus:outline-none overflow-hidden w-full"
      style={{
        background: isSelected
          ? `linear-gradient(135deg, ${company.bg}, white 60%, ${company.bg})`
          : "white",
        border: `2px solid ${isSelected ? company.color : "#EBEBEB"}`,
        boxShadow: isSelected
          ? `0 8px 32px ${company.color}28, 0 2px 8px ${company.color}18, inset 0 1px 0 rgba(255,255,255,0.9)`
          : hovered
          ? `0 8px 24px rgba(0,0,0,0.10), 0 2px 6px rgba(0,0,0,0.06)`
          : `0 2px 8px rgba(0,0,0,0.05)`,
        transition: "box-shadow 0.3s ease, border-color 0.3s ease, background 0.3s ease",
      }}
    >
      {/* Shimmer overlay on hover */}
      <AnimatePresence>
        {(hovered || isSelected) && (
          <motion.div
            initial={{ opacity: 0, x: "-100%" }}
            animate={{ opacity: 1, x: "100%" }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.6, ease: "easeInOut" }}
            className="absolute inset-0 pointer-events-none"
            style={{
              background: `linear-gradient(105deg, transparent 40%, ${company.color}12 50%, transparent 60%)`,
            }}
          />
        )}
      </AnimatePresence>

      {/* Subtle top gradient bar */}
      <div
        className="absolute top-0 left-0 right-0 h-0.5 rounded-t-3xl transition-opacity duration-300"
        style={{
          background: `linear-gradient(90deg, transparent, ${company.color}, transparent)`,
          opacity: isSelected ? 1 : 0,
        }}
      />

      {/* Selected check badge */}
      <AnimatePresence>
        {isSelected && (
          <motion.div
            initial={{ scale: 0, opacity: 0, rotate: -20 }}
            animate={{ scale: 1, opacity: 1, rotate: 0 }}
            exit={{ scale: 0, opacity: 0, rotate: 20 }}
            transition={{ type: "spring", stiffness: 500, damping: 25 }}
            className="absolute top-2.5 right-2.5 w-5 h-5 rounded-full flex items-center justify-center shadow-md"
            style={{ background: company.color }}
          >
            <Check className="w-3 h-3 text-white" strokeWidth={3.5} />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Logo container — large, glowing, pill-shaped */}
      <motion.div
        animate={isSelected ? { scale: 1.08 } : { scale: 1 }}
        transition={{ type: "spring", stiffness: 300, damping: 20 }}
        className="w-20 h-20 rounded-2xl flex items-center justify-center overflow-hidden relative"
        style={{
          background: `linear-gradient(145deg, ${company.bg}, white)`,
          boxShadow: isSelected
            ? `0 4px 16px ${company.color}35, inset 0 1px 0 rgba(255,255,255,0.8)`
            : `0 2px 8px rgba(0,0,0,0.07), inset 0 1px 0 rgba(255,255,255,0.9)`,
        }}
      >
        <img
          src={company.logo}
          alt={company.name}
          className="w-14 h-14 object-contain"
          onError={(e) => {
            e.target.style.display = "none";
            e.target.nextSibling.style.display = "flex";
          }}
        />
        <div
          className="w-14 h-14 hidden items-center justify-center rounded-lg text-xs font-black"
          style={{ color: company.color }}
        >
          {company.name.slice(0, 2).toUpperCase()}
        </div>
      </motion.div>

      {/* Company name */}
      <motion.span
        animate={{ color: isSelected ? company.color : "#374151" }}
        transition={{ duration: 0.2 }}
        className="text-[13px] font-bold tracking-tight leading-tight"
      >
        {company.name}
      </motion.span>

      {/* Selected underline dot */}
      <AnimatePresence>
        {isSelected && (
          <motion.div
            initial={{ scaleX: 0 }}
            animate={{ scaleX: 1 }}
            exit={{ scaleX: 0 }}
            className="absolute bottom-2 w-4 h-0.5 rounded-full"
            style={{ background: company.color }}
          />
        )}
      </AnimatePresence>
    </motion.button>
  );
};

/* ---------------- Main Page ---------------- */

const SelectRolesAndCompany = ({ companyType, setCompanyType, role, setRole }) => {
  const COMPANY_ROLES = {
    Google: ["Software Engineer", "Product Manager", "Data Scientist", "UX Designer", "DevOps Engineer", "ML Engineer"],
    Microsoft: ["Software Engineer", "Product Manager", "Data Analyst", "Cloud Architect", "Security Engineer", "Program Manager"],
    Amazon: ["Software Development Engineer", "Product Manager", "Data Engineer", "Solutions Architect", "Operations Manager", "ML Scientist"],
    Meta: ["Software Engineer", "Product Manager", "Data Scientist", "Research Engineer", "UX Researcher", "Backend Engineer"],
    Apple: ["Software Engineer", "Hardware Engineer", "Product Designer", "ML Engineer", "QA Engineer", "Systems Engineer"],
    Netflix: ["Software Engineer", "Data Scientist", "Product Manager", "Site Reliability Engineer", "Content Engineer", "Backend Engineer"],
    Nvidia: ["Software Engineer", "Hardware Engineer", "ML Engineer", "CUDA Developer", "Systems Architect", "Research Scientist"],
    Salesforce: ["Software Engineer", "Solution Engineer", "Product Manager", "Salesforce Developer", "Cloud Consultant", "Data Architect"],
    Adobe: ["Software Engineer", "UX Designer", "Product Manager", "Frontend Engineer", "Data Scientist", "Creative Technologist"],
    Uber: ["Software Engineer", "Product Manager", "Data Scientist", "Backend Engineer", "Mobile Engineer", "Operations Analyst"],
    Airbnb: ["Software Engineer", "Product Manager", "Data Scientist", "UX Designer", "Frontend Engineer", "Trust & Safety Analyst"],
    Spotify: ["Software Engineer", "Data Engineer", "Product Manager", "ML Engineer", "Backend Engineer", "Audio Engineer"],
  };

  const [roles, setRoles] = useState([]);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const navigate = useNavigate();

  useEffect(() => { if (!companyType) setSelectedCompany(null); }, [companyType]);
  useEffect(() => {
    if (!companyType) { setRoles([]); return; }
    setRoles(COMPANY_ROLES[companyType] || []);
  }, [companyType]);

  const handleCompanySelect = (company) => {
    if (selectedCompany?.name === company.name) {
      setSelectedCompany(null); setCompanyType(null); setRole(null);
    } else {
      setSelectedCompany(company); setCompanyType(company.name); setRole(null);
    }
  };

  const handleRoleSelect = (selectedRole) => { if (companyType) setRole(selectedRole); };
  const handleStartInterview = () => { if (companyType && role) navigate("/services/check-your-ability/interview/rounds"); };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1, delayChildren: 0.1 } },
  };
  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1, transition: { type: "spring", stiffness: 100, damping: 15 } },
  };

  return (
    <div className="min-h-screen bg-[#FDFBF9] p-6 font-sans selection:bg-[#D4F478] selection:text-black flex items-center justify-center relative overflow-hidden">
      <div className="fixed inset-0 pointer-events-none -z-50">
        <div className="absolute top-[-10%] right-[-5%] w-[60vw] h-[60vw] bg-gradient-to-b from-blue-50 to-transparent rounded-full blur-[120px] opacity-60" />
        <div className="absolute bottom-[-10%] left-[-10%] w-[50vw] h-[50vw] bg-gradient-to-t from-pink-50 to-transparent rounded-full blur-[120px] opacity-60" />
      </div>

      <motion.div
        initial="hidden"
        animate="visible"
        variants={containerVariants}
        className="w-full max-w-3xl bg-white/40 backdrop-blur-xl border border-white/60 rounded-[3rem] shadow-2xl shadow-gray-200/50 p-10 md:p-16 space-y-10 relative overflow-hidden"
      >
        <motion.div
          animate={{ y: [0, -12, 0], rotate: [0, 4, 0] }}
          transition={{ duration: 6, repeat: Infinity, ease: "easeInOut" }}
          className="absolute -top-8 -right-8 w-32 h-32 bg-purple-200/40 rounded-full blur-3xl pointer-events-none"
        />

        {/* Header */}
        <motion.div variants={itemVariants} className="text-center space-y-3 relative z-10">
          <div className="flex items-center justify-center gap-2 mb-2">
            <motion.div animate={{ rotate: [0, 360] }} transition={{ duration: 20, repeat: Infinity, ease: "linear" }}>
              <Sparkles className="w-6 h-6 text-[#D4F478]" />
            </motion.div>
            <span className="text-sm font-bold uppercase tracking-widest text-gray-400">AI-Powered Practice</span>
          </div>
          <h1 className="text-4xl md:text-5xl font-black tracking-tight text-gray-900 leading-tight">Check Your Ability</h1>
          <motion.div initial={{ width: 0 }} animate={{ width: 100 }} transition={{ delay: 0.5, duration: 1 }}
            className="h-1.5 bg-[#D4F478] mx-auto rounded-full" />
          <p className="text-gray-500 text-lg leading-relaxed max-w-xl mx-auto font-medium pt-2">
            Pick a company and role to begin your mock interview
          </p>
        </motion.div>

        {/* Company Cards Grid */}
        <motion.div variants={itemVariants} className="relative z-10 space-y-3">
          <label className="text-sm font-bold text-gray-700 ml-1 block">Select Company</label>
          <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
            {BIG_TECH_COMPANIES.map((company, index) => (
              <motion.div
                key={company.name}
                initial={{ opacity: 0, y: 16 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.04 * index, duration: 0.3 }}
              >
                <CompanyCard
                  company={company}
                  isSelected={selectedCompany?.name === company.name}
                  onClick={() => handleCompanySelect(company)}
                />
              </motion.div>
            ))}
          </div>

          <AnimatePresence>
            {selectedCompany && (
              <motion.div
                initial={{ opacity: 0, y: -6, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -6, scale: 0.95 }}
                className="flex items-center gap-2 mt-1"
              >
                <div className="w-2 h-2 rounded-full" style={{ background: selectedCompany.color }} />
                <span className="text-sm font-semibold text-gray-600">{selectedCompany.name} selected</span>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>

        {/* Role Selector */}
        <motion.div variants={itemVariants} className="relative z-10 space-y-2">
          <label className="text-sm font-bold text-gray-700 ml-1 block">Select Role</label>
          <SelectionButton
            placeholder="Select Role"
            value={role}
            options={roles}
            onSelect={handleRoleSelect}
            disabled={!companyType}
            dropdownDirection="up"
          />
        </motion.div>

        {/* CTA */}
        <motion.div variants={itemVariants} className="pt-8 border-t border-gray-200/50 flex justify-center relative z-10">
          <motion.button
            type="button"
            whileHover={companyType && role ? "hover" : {}}
            whileTap={companyType && role ? "tap" : {}}
            onClick={handleStartInterview}
            disabled={!companyType || !role}
            className={`flex items-center gap-0 group cursor-pointer ${!companyType || !role ? "opacity-50 cursor-not-allowed" : ""}`}
          >
            <span className={`px-10 py-4 rounded-l-full font-bold text-lg shadow-xl z-10 relative
              ${companyType && role ? "bg-[#1A1A1A] text-white shadow-gray-300/50" : "bg-gray-300 text-gray-500"}`}>
              Start Your Interview
            </span>
            <motion.span
              className={`w-14 h-[3.75rem] flex items-center justify-center rounded-r-full border-l-2 origin-left transition-colors
                ${companyType && role ? "bg-[#D4F478] border-[#1A1A1A] group-hover:bg-[#cbf060]" : "bg-gray-200 border-gray-300"}`}
              variants={{ hover: { x: 5 }, tap: { x: 0 } }}
            >
              <ArrowRight className={`w-6 h-6 transition-transform duration-300
                ${companyType && role ? "text-black group-hover:rotate-[-45deg]" : "text-gray-500"}`} />
            </motion.span>
          </motion.button>
        </motion.div>

        {/* Progress indicator */}
        <motion.div variants={itemVariants} className="flex items-center justify-center gap-2 pt-4">
          <div className={`w-2 h-2 rounded-full transition-all ${companyType ? "bg-[#D4F478]" : "bg-gray-300"}`} />
          <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Step 2 of 3</span>
          <div className={`w-2 h-2 rounded-full transition-all ${role ? "bg-[#D4F478]" : "bg-gray-300"}`} />
        </motion.div>
      </motion.div>
    </div>
  );
};

export default SelectRolesAndCompany;